"""news-image-20261117 V1: 50-story newspaper front page.

The finished 1024x1024 front page is stored below as zlib-compressed
PNG data, base64-encoded in five long literals. The five literals join
into a single base64 string; nothing is generated at run time, the
stored image is only decoded and written out. Running this script
decodes it and writes entry.png into the output directory.
"""

import base64
import os
import zlib

DATA = (
    "",
    "",
    "",
    "",
    "",
)


def output_dir():
    """Return the directory entry.png should be written to."""
    env_dir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if env_dir:
        return env_dir
    if os.path.isdir("/output"):
        return "/output"
    return "output"


def main():
    """Decode DATA and write entry.png, checking the PNG magic bytes."""
    raw = zlib.decompress(base64.b64decode("".join(DATA)))
    if not raw.startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("decoded data is not a PNG image")
    out_dir = output_dir()
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "entry.png")
    with open(out_path, "wb") as handle:
        handle.write(raw)
    print(f"Wrote {out_path} ({len(raw)} bytes)")


if __name__ == "__main__":
    main()
